pub fn run_ops(ops: List[Str]) -> Result[Int, Str] {
  var bal = 0
  var i = 0
  for op in ops {
    i = i + 1
    let parts = op.split(" ")
    if parts.len() != 2 {
      return Err("bad op at op {i}")
    }
    let verb = parts.get_or(0, "")
    let amount = match parts.get_or(1, "").to_int() {
      Some(n) => n,
      None => -1,
    }
    if amount < 0 {
      return Err("bad op at op {i}")
    }
    if verb == "deposit" {
      bal = bal + amount
    } else if verb == "withdraw" {
      if bal - amount < 0 {
        return Err("insufficient funds at op {i}")
      }
      bal = bal - amount
    } else {
      return Err("bad op at op {i}")
    }
  }
  return Ok(bal)
}
